// Auto-generated app icon: black breasts composited onto a WHITE opaque
// background (the transparent original was invisible on the dark launch splash).
// Inlined as base64 so it ships in the JS bundle and is served by Next route
// handlers — Firebase App Hosting does not serve files from /public.
const PNG_BASE64 =
  "";

const BYTES = Buffer.from(PNG_BASE64, "base64");

/** A cached PNG Response for the app icon, for use from route handlers. */
export function iconPngResponse(): Response {
  return new Response(BYTES, {
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": "public, max-age=31536000, immutable",
    },
  });
}
